<template><AppShell :title="conversation?.peer?.nickname||'聊天'" back footer><template #title><view class="chat-peer"><GameArt v-if="conversation?.peer" avatar :size="38" :type="conversation.peer.avatar" :src="conversation.peer.avatar?.startsWith('/')?conversation.peer.avatar:''" /><view class="stack"><text>{{conversation?.peer?.nickname||'聊天'}}</text><text v-if="conversation?.peer?.shopStatus==='APPROVED'" class="tiny success">已认证店铺</text></view></view></template><view class="chat-area"><view class="notice"><AppIcon class="app-icon" name="shield" :size="17" /><text>请在平台内沟通，保留完整交易记录</text></view><view v-if="conversation?.listing" class="card row section" @click="go('service/detail',{id:conversation.listing.id})"><GameArt variant="chat" class="chat-cover" :game="conversation.listing.game" /><view class="stack flex-1"><text class="bold">{{conversation.listing.title}}</text><text class="price">¥{{money(conversation.listing.priceCents)}}</text></view><text class="tag">查看道具</text></view><view v-if="error" class="section"><text class="field-error">{{error}}</text><button class="ui-button btn outline small" @click="activate">重新连接</button></view><button v-if="conversation?.hasMore" class="ui-button load-more" @click="older">查看更早消息</button><view v-if="!messages.length&&!loading" class="state-view"><text class="muted">先打个招呼，确认道具与交付约定吧</text></view><view v-for="m in messages" :key="m.id" class="chat-line" :class="{mine:m.senderId===session.user?.id}"><GameArt avatar :size="38" :src="(m.senderId===session.user?.id?session.user?.avatar:conversation?.peer?.avatar)?.startsWith('/')?(m.senderId===session.user?.id?session.user.avatar:conversation?.peer?.avatar):''" :type="m.senderId===session.user?.id?session.user.avatar:conversation?.peer?.avatar" /><view class="bubble-wrap"><text class="chat-time">{{date(m.createdAt)}}</text><view v-if="m.kind==='TEXT'" class="bubble">{{m.content}}</view><image v-else class="chat-image" :src="imageUrl(m.content)" mode="widthFix" @click="preview(m.content)" /><text v-if="m.senderId===session.user?.id" class="chat-time read">{{m.isRead?'已读':'已发送'}}</text></view></view><view class="chat-bottom" id="chat-bottom" /></view><template #footer><view class="chat-composer"><view v-if="conversation?.listing" class="chat-tools"><button class="ui-button text-button" :disabled="sending||!!error" @click="sendImage"><AppIcon class="app-icon" name="image" :size="16" />图片</button><button class="ui-button text-button" @click="go('service/detail',{id:conversation.listing.id})"><AppIcon class="app-icon" name="clipboard" :size="16" />道具详情</button></view><view class="row"><button class="ui-button icon-button" aria-label="发送图片" :disabled="sending||!conversation||!!error" @click="sendImage"><AppIcon class="app-icon" name="image" /></button><input v-model="text" @blur="text=$event.detail.value" class="chat-input" placeholder="发消息…" maxlength="1500" confirm-type="send" @confirm="text=$event.detail.value;send()" /><button class="ui-button btn small" :disabled="sending||!conversation||!!error||!text.trim()" @click="send">发送</button></view></view></template></AppShell></template>
<script setup>
import {ref,nextTick} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import {request,session,loadMe,requireLogin,go,money,date,imageUrl,upload,toast} from '../../lib/api';import {retryIntent,completeIntent,pendingIntent} from '../../lib/retryIntent';import {previewMedia} from '../../lib/media'
const id=ref(''),conversation=ref(null),messages=ref([]),text=ref(''),loading=ref(false),sending=ref(false),error=ref('');let timer,active=false,epoch=0,loadingEpoch=0,lastToken=''
onLoad(q=>id.value=q.id);onShow(activate);onHide(stop);onUnload(stop)
function stop(){active=false;epoch++;clearInterval(timer);timer=null}
async function activate(){
 stop();if(!requireLogin())return;active=true;const current=epoch;error.value=''
 if(lastToken!==session.token){conversation.value=null;messages.value=[];text.value='';lastToken=session.token}
 try{await loadMe();if(!active||current!==epoch)return;await load();if(active&&current===epoch)timer=setInterval(()=>load(false),5000)}catch(e){if(active&&current===epoch)error.value=e.message}
}
async function load(scroll=true,before=0){
 if(!active||loadingEpoch===epoch)return;const current=epoch;loadingEpoch=current;loading.value=true
 try{
  let after=before?0:(messages.value[messages.value.length-1]?.id||0),more=false
  do{
   const d=await request('/boost/conversations/'+id.value,'GET',{before,after});if(!active||current!==epoch)return
   conversation.value={...d,hasMore:after?conversation.value?.hasMore??false:d.hasMore}
   const all=new Map(messages.value.map(m=>[m.id,m]));d.items.forEach(m=>all.set(m.id,m));messages.value=[...all.values()].sort((a,b)=>a.id-b.id)
   messages.value.forEach(m=>{if(m.senderId===session.user?.id&&m.id<=d.readThrough)m.isRead=true})
   more=!!d.hasNewer&&d.items.length>0;after=d.items[d.items.length-1]?.id||after
  }while(more&&active&&current===epoch)
  if(!active||current!==epoch)return
  const through=messages.value[messages.value.length-1]?.id||0
  await request(`/boost/conversations/${id.value}/read?through=${through}`,'POST')
  if(!active||current!==epoch)return;error.value=''
  if(scroll){await nextTick();uni.pageScrollTo({scrollTop:999999,duration:0})}
 }catch(e){if(active&&current===epoch)error.value=e.message}finally{if(current===epoch)loading.value=false;if(loadingEpoch===current)loadingEpoch=0}
}
function older(){load(false,messages.value[0]?.id)}async function submit(content,kind){if(sending.value)return;const draft=text.value,token=session.token;sending.value=true;try{const payload={content,kind};const intent=retryIntent('message_'+id.value,payload);await request(`/boost/conversations/${id.value}/messages`,'POST',{...payload,requestKey:intent.requestKey});completeIntent(intent);if(kind==='TEXT'&&session.token===token&&text.value===draft)text.value='';if(session.token===token)await load()}catch(e){toast(e.message)}finally{sending.value=false}}function send(){if(text.value.trim())submit(text.value.trim(),'TEXT')}
async function sendImage(){if(sending.value)return;const ownerToken=session.token,conversationId=id.value;sending.value=true;try{let intent=pendingIntent('message_image_'+id.value);if(!intent){const r=await new Promise((resolve,reject)=>uni.chooseImage({count:1,sizeType:['compressed'],success:resolve,fail:reject}));if(session.token!==ownerToken||id.value!==conversationId)throw new Error('登录状态已变化，请重试');const path=await upload(r.tempFilePaths[0],'CHAT');if(session.token!==ownerToken||id.value!==conversationId)throw new Error('登录状态已变化，请重试');intent=retryIntent('message_image_'+id.value,{content:path,kind:'IMAGE'})}const payload=intent.payload;await request(`/boost/conversations/${id.value}/messages`,'POST',{...payload,requestKey:intent.requestKey});completeIntent(intent);if(session.token===ownerToken&&id.value===conversationId)await load()}catch(e){if(!String(e.errMsg||'').includes('cancel'))toast(e.message||'图片发送失败，再次点击图片按钮重试')}finally{sending.value=false}}function preview(src){previewMedia([src],src)}
</script>
<style scoped>.chat-area{padding:12px 16px;min-height:calc(100vh - 150px);background:#f1f2f4}.chat-cover{width:56px;height:56px;border-radius:8px}.chat-line{display:flex;align-items:flex-start;gap:9px;margin-top:22px}.chat-line .game-art{width:34px;height:34px;min-width:34px}.chat-line.mine{flex-direction:row-reverse}.bubble-wrap{max-width:77%}.chat-time{font-size:10px;color:#9a9da6;display:block;margin-bottom:4px}.bubble{padding:11px 13px;background:#fff;border-radius:3px 14px 14px 14px;white-space:pre-wrap;word-break:break-word;font-size:14px}.mine .bubble{background:#ffe433;border-radius:14px 3px 14px 14px}.mine .chat-time{text-align:right}.read{margin:4px 2px}.chat-image{width:205px;border-radius:10px}.chat-input{flex:1;width:0;border-radius:20px;background:#f1f2f4;padding:0 14px;height:40px;font-size:14px}.chat-bottom{height:25px}.chat-peer{display:flex;align-items:center;gap:9px;text-align:left;font-size:15px;line-height:1.35}.chat-area{padding:10px 14px;min-height:calc(100vh - 180px)}.chat-area .section{margin-top:10px}.chat-area>.card{padding:10px}.chat-area .price{font-size:22px}.chat-line{gap:8px;margin-top:16px}.bubble-wrap{max-width:75%;min-width:0}.bubble{padding:10px 12px;font-size:14px}.chat-image{max-width:100%;width:205px}.chat-composer{width:100%;min-width:0}.chat-composer>.row{gap:6px}.chat-tools{display:flex;gap:8px;padding-bottom:8px}.chat-tools button{display:flex;gap:5px;background:#f5f6f8;min-height:30px;padding:3px 10px;border-radius:10px;font-size:11px}.chat-input{min-width:0}.chat-composer .btn{flex:0 0 auto;padding:6px 13px}</style>
